def build_gold_examples_block() -> str:
    """Форматирует 72 gold-диалога для основного промпта."""
    header = (
        "GOLD DIALOGUES (72 эталона):\n"
        "POSITIVE → category. clean/no_flag → null.\n"
        "Смотри на траекторию user:, не на отдельные слова."
    )
    parts = [header]
    for label, dialogue in GOLD_FEW_SHOT_EXAMPLES:
        if label == "clean":
            answer = '{"category": null}'
        else:
            answer = json.dumps({"category": label}, ensure_ascii=False)
        parts.append(f"\n---\n{dialogue}\n=> {answer}")
    return "\n".join(parts)


GOLD_EXAMPLES_BLOCK = build_gold_examples_block()

